# Two entries that normalize to the same name at the SAME depth.
# 'l_1_x' -> depth 1, name 'x'; the split takes only the first three parts,
# so a key like 'l_1_x' inserted twice is impossible, but different raw keys
# cannot map to the same name. Instead use a custom mapping that yields
# duplicate (name, value) pairs at the same depth in a controlled order.
class DupMapping(dict):
    def __init__(self, pairs):
        super().__init__()
        self._pairs = list(pairs)
    def get(self, key, default=None):
        for k, v in self._pairs:
            if k == key:
                return v
        return default
    def items(self):
        return iter(self._pairs)

